tinymce.PluginManager.add('tab', function(editor, url) {

    editor.ui.registry.addButton('tab', {
        text: '.tab',
        tooltip: 'Transformar em Tablatura',
        // icon: false,
        onAction: function() {

            editor.selection.setContent('<p class="tab">' + editor.selection.getContent() + '</tab>');
        }
    });

    editor.ui.registry.addMenuItem('tab', {
        text: 'Transformar em Tablarura',
        context: 'insert',
        onAction: function() {

            editor.selection.setContent('<p class="tab">' + editor.selection.getContent() + '</p>');
        }
    });

});